// observes a partially written batch.
type Store struct {
	dir      string
	nodesDir string
	lockPath string
}

// OpenStore opens (and if needed creates) a data directory.
func OpenStore(dir string) (*Store, error) {
	if err := os.MkdirAll(dir, 0o755); err != nil {
